package posemap

import "testing"

func TestReady(t *testing.T) {
	if !Ready() {
		t.Fatal("baseline not ready")
	}
}

// Package posemap 是本地定位与地图的本地基线。
package posemap

// Ready 表示基线可以运行。
func Ready() bool { return true }

