func TestHistoryQuery(t *testing.T) {
	m := newTestMap(t, defaultCfg())

	if _, _, err := m.Import("seg1", []Frame{
		{Time: 2000, DX: 1},
		{Time: 3000, DX: 1},
	}); err != nil {
		t.Fatal(err)
	}

	cases := []struct {
		t    int64
		want float64
		ok   bool
	}{
		{999, 0, false},  // 早于初始时间
		{1000, 0, true},  // 恰为初始时间
		{1500, 0, true},  // 初始与第一帧之间
		{2000, 1, true},  // 恰为第一帧
		{2500, 1, true},  // 两帧之间
		{3000, 2, true},  // 恰为第二帧
		{9999, 2, true},  // 晚于最后一帧
	}
	for _, c := range cases {
		p, ok := m.HistoryAt(c.t)
		if ok != c.ok {
			t.Errorf("HistoryAt(%d) ok = %v, want %v", c.t, ok, c.ok)
			continue
		}
		if ok {
			approx(t, "x", p.X, c.want)
		}
	}
}

