// InitialVariance 必须非负；MaxInterval 与 MergeDistance 必须为正；
// 所有数值都必须是有限数。
type Config struct {
	// InitialTime 是初始时间（整数毫秒）。
	InitialTime int64
	// InitialX、InitialY 是初始位置（米）。
	InitialX, InitialY float64

